/** One palette for the complete voxel sequence, prepared AFTER voxelization.
 * Never infer a different palette from each rendered camera or animation frame. */
const voxelMapper = (grids: PackedGrid[], colors: number): CartoonColorMapper => {
  const count = grids.reduce((sum, grid) => sum + grid.colors.length, 0);
  const stride = Math.max(1, Math.ceil(count / 131072));
  function* samples(): Generator<readonly number[]> {
    let sample = 0;
    for (const grid of grids) for (let i = 0; i < grid.colors.length; i++, sample++) if (sample % stride === 0) yield keyToRgb(grid.colors[i]);
  }
  return createCartoonColorMapper(createCartoonPalette(samples(), colors));
};

