/** GGXrd-style presets: one hard lit/shadow boundary with a tinted shadow,
 * smoothed shading normals, and depth-discontinuity inner lines that reach the
 * outline node as a mask at the pixelized size. */
const celGraph = (dots: boolean, cel: boolean): Graph => {
  const render: Record<string, unknown> = cel
    ? { lighting: 'cel', cartoon_smoothing: 0.65, normal_smooth: 0.75, inner_lines: true }
    : { lighting: 'unlit', cartoon_smoothing: 0.65, inner_lines: true };
  const nodes: NodeSpec[] = [
    ['mesh_input', 40, 160],
    ['cartoon_render', 320, 120, render],
  ];
  const links: LinkSpec[] = [[0, 'mesh', 1, 'mesh']];
  if (dots) nodes.push(['pia_auto', 600, 120, { long_side: 256, color_count: 16, iterations: 10, compactness: 20, temporal_stability: 0 }]);
  nodes.push(['outline', dots ? 880 : 600, 120, { outline_mode: 'pixel_perfect', thickness: dots ? 1 : 2, draw_outline: true }]);
  nodes.push(['output', dots ? 1160 : 880, 160]);
  for (let i = 1; i < nodes.length - 1; i++) links.push([i, 'image', i + 1, 'image']);
  links.push([1, 'lines', nodes.length - 2, 'lines']);
  return build(nodes, links);
};

