const attachPropSpecs = async (mesh: MeshData, specs: PropSpec[], props: PropAccess | null, report: (info: Partial<NodeInfo>) => void, tick: () => Promise<void>): Promise<AttachResult> => {
  if (!specs.length) return { mesh, attachments: [], warnings: [] };
