  for (const spec of specs) {
    try {
      const asset = props ? await props.load(spec.id) : null;
      if (asset && asset.kind === 'mesh' && asset.mesh.prims.length) sources.push({ spec, mesh: asset.mesh });
      else missing.add(spec.id);
    } catch { missing.add(spec.id); }
    await tick();
  }
  const result = attachProps(mesh, sources);
  report({ props: specs.map((spec) => ({
    id: spec.id, name: spec.name, socket: spec.socket, missing: missing.has(spec.id),
    attached: (result.attachments.find((a) => a.spec === spec)?.joint ?? -1) >= 0,
  })) });
  return result;
};

