const WORKS_MAX = 24;
const WORK_MAX_BYTES = 64 * 1024 * 1024;
const PROP_STORE = 'props';
const PROPS_MAX = 32;

// ---------- 장비(무기) GLB (IndexedDB, id 별 보관, 오래된 것부터 정리) ----------
export interface StoredProp { id: string; name: string; blob: Blob; size: number; addedAt: number }

export const savePropFile = async (id: string, name: string, blob: Blob): Promise<void> => {
  try {
    const db = await openDb();
    const tx = db.transaction(PROP_STORE, 'readwrite');
    const store = tx.objectStore(PROP_STORE);
    store.put({ id, name, blob, size: blob.size, addedAt: Date.now() } satisfies StoredProp);
    const all = await reqPromise(store.getAll() as IDBRequest<StoredProp[]>);
    const extra = all.filter((p) => p.id !== id).sort((a, b) => b.addedAt - a.addedAt).slice(PROPS_MAX - 1);
    for (const p of extra) store.delete(p.id);
    await txDone(tx);
    db.close();
  } catch { /* ignore */ }
};

export const loadPropFile = async (id: string): Promise<StoredProp | null> => {
  try {
    const db = await openDb();
