  } catch { return null; }
};

export const deletePropFile = async (id: string): Promise<void> => {
  try {
    const db = await openDb();
    const tx = db.transaction(PROP_STORE, 'readwrite');
    tx.objectStore(PROP_STORE).delete(id);
    await txDone(tx);
    db.close();
  } catch { /* ignore */ }
};

