/** prop-local → socket-frame-local: grip at the origin, long axis along the
 * frame's up (blade upright), width along the fingers so the flat of a blade
 * faces the viewer in a front sprite, uniform size. */
const alignMatrix = (shape: PropShape, size: number, height: number): Mat4 => {
  const a: Vec3 = [0, 0, 0], b: Vec3 = [0, 0, 0];
  a[shape.axis] = shape.tipSign; b[shape.second] = 1;
  const c = cross(a, b); // right-handed: c → right, a → up, b → forward
  // Rows are the prop-space basis vectors: this rotation maps c to +X, a to +Y, b to +Z.
  const rotate = new Float64Array([c[0], a[0], b[0], 0, c[1], a[1], b[1], 0, c[2], a[2], b[2], 0, 0, 0, 0, 1]);
  const scale = Math.max(1e-6, (Math.max(1, size) / 100) * height / shape.length);
  return mat4Multiply(scaling(scale), mat4Multiply(rotate, translation([-shape.grip[0], -shape.grip[1], -shape.grip[2]])));
};

/** frame-local user adjustment: fist offset, then roll/pitch/yaw, then translation. */
const userMatrix = (spec: PropSpec, socket: PropSocket, height: number): Mat4 => {
  const [ox, oy, oz] = spec.offset.map(v => (Number.isFinite(v) ? v : 0) * height / 100) as Vec3;
  const [yaw, pitch, roll] = spec.rotate.map(v => (Number.isFinite(v) ? v : 0)) as Vec3;
  const grip = socket === 'head' ? 0 : height * 0.04; // the fist sits a little past the wrist joint
  let m = translation([ox, oy, oz + grip]);
  m = mat4Multiply(m, axisRotation([0, 1, 0], yaw));
  m = mat4Multiply(m, axisRotation([1, 0, 0], pitch));
  m = mat4Multiply(m, axisRotation([0, 0, 1], roll));
  return m;
};

