/** prop-local → socket-frame-local: grip at the origin, uniform size, and the
 * long axis either along the fingers ('along', extending the hand) or upright
 * ('up'). The width axis is placed so the flat of a blade faces the viewer in
 * a front sprite. `flip` holds the prop by its other end. */
const alignMatrix = (shape: PropShape, spec: PropSpec, height: number): Mat4 => {
  const tipSign = spec.flip ? -shape.tipSign : shape.tipSign;
  const grip: Vec3 = [shape.grip[0], shape.grip[1], shape.grip[2]];
  if (spec.flip) grip[shape.axis] = tipSign > 0 ? shape.min[shape.axis] + shape.length * 0.1 : shape.max[shape.axis] - shape.length * 0.1;
