/** the prop's rest-world bounds (after attaching) — the page places a default sway box near it */
export const attachmentBounds = (a: PropAttachment): { min: Vec3; max: Vec3 } | null => {
  const min: Vec3 = [Infinity, Infinity, Infinity], max: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (const p of a.prims) for (let i = 0; i < p.pos.length; i += 3) for (let k = 0; k < 3; k++) { if (p.pos[i + k] < min[k]) min[k] = p.pos[i + k]; if (p.pos[i + k] > max[k]) max[k] = p.pos[i + k]; }
  return Number.isFinite(min[0]) ? { min, max } : null;
};

